const text = $('Telegram Trigger').first().json.message.text

const match = text.match(/https?:\/\/[^\s]+/i);

if (!match) {
  throw new Error("No URL found in the message");
}

return [
  {
    json: {
      google_maps_url: match[0]
    }
  }
];

const item = $input.first().json;

// Convert the entire response to text so we don't care
// which field n8n put the HTML in.
const text = JSON.stringify(item);

// Decode escaped/encoded Google Maps content
const decoded = text
  .replace(/\\u0026/g, '&')
  .replace(/\\u003d/g, '=')
  .replace(/\\u0021/g, '!')
  .replace(/\\\\/g, '\\');

// Pattern 1: Google Maps @latitude,longitude
let match = decoded.match(/@(-?\d{1,3}\.\d+),(-?\d{1,3}\.\d+)/);

// Pattern 2: Google internal !3dLAT !4dLNG
if (!match) {
  match = decoded.match(/!3d(-?\d{1,3}\.\d+).*?!4d(-?\d{1,3}\.\d+)/);
}

// Pattern 3: URL-encoded !3dLAT %21 ... !4dLNG
if (!match) {
  match = decoded.match(/!3d(-?\d{1,3}\.\d+).*?%21.*?!4d(-?\d{1,3}\.\d+)/);
}

// Pattern 4: encoded %213dLAT ... %214dLNG
if (!match) {
  match = decoded.match(/%213d(-?\d{1,3}\.\d+).*?%214d(-?\d{1,3}\.\d+)/);
}

if (!match) {
  throw new Error(
    "Coordinates not found. Response starts with: " +
    decoded.substring(0, 1000)
  );
}

return [
  {
    json: {
      latitude: Number(match[1]),
      longitude: Number(match[2])
    }
  }
];
